//! Raw FFI bindings to the Triton Inference Server backend and server C API
//! (`tritonbackend.h`, `tritonserver.h` of the release in `.gitmodules`), generated by bindgen.
//! Use [triton-ng](https://docs.rs/triton-ng) instead of these directly.
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
// The doc comments are Triton's header comments as bindgen copies them:
// Doxygen markup and <placeholders>, not Markdown.
#![allow(
    rustdoc::invalid_html_tags,
    rustdoc::broken_intra_doc_links,
    rustdoc::bare_urls
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
